const TOKEN = "t6OZHB0jVRgpcD0xaeMYB6h5uJhCWx0JKTiLp6oVv_k";
const AUTH = "Basic " + btoa("0:" + TOKEN);
const H = { Authorization: AUTH, "Content-Type": "application/json" };

async function api(method: string, path: string, body?: any, contentType?: string) {
  const url = `${BASE}${path}`;
  const opts: any = { method, headers: contentType === "formdata" ? { Authorization: AUTH } : H };
  if (body && contentType === "formdata") opts.body = body;
  else if (body) opts.body = JSON.stringify(body);
  const r = await fetch(url, opts);
  const text = await r.text();
  console.log(`${method} ${path} → ${r.status}`);
  if (!r.ok) { console.log("ERROR:", text); throw new Error(`${r.status} ${text}`); }
  return JSON.parse(text);
}

// Invoice data from PDF
const supplier = {
  name: "Nordlicht GmbH",
  orgNr: "871162069",
  street: "Nygata 53",
  postalCode: "9008",
  city: "Tromsø",
  bban: "28390913577",
};
const inv = {
  number: "INV-2026-7611",
  date: "2026-04-06",
  dueDate: "2026-05-06",
  description: "Nettverkstjenester",
  net: 35650,
  vat: 8912,
  gross: 44562,
  account: 6300,
};

async function main() {
  // Step 1: Create supplier
  const s = await api("POST", "/supplier", {
    name: supplier.name,
    organizationNumber: supplier.orgNr,
    postalAddress: {
      addressLine1: supplier.street,
      postalCode: supplier.postalCode,
      city: supplier.city,
      country: { id: 161 },
    },
    physicalAddress: {
      addressLine1: supplier.street,
      postalCode: supplier.postalCode,
      city: supplier.city,
      country: { id: 161 },
    },
    bankAccountPresentation: [{ bban: supplier.bban }],
  });
  const supplierId = s.value.id;
  console.log("Supplier ID:", supplierId);

  // Step 2: Get expense account ID
  const acct = await api("GET", `/ledger/account?number=${inv.account}&isApplicableForSupplierInvoice=true&fields=*`);
  const expenseAccountId = acct.values[0].id;
  console.log("Expense account ID:", expenseAccountId);

  // Also need the supplier ledger account (2400)
  const supplierAcct = await api("GET", `/ledger/account?number=2400&fields=id`);
  // Wait — this is an extra call. Let me check: the trusted standard says 5 calls.
  // Step 2 is a single GET for the expense account. For the supplier ledger account (2400),
  // the posting uses supplier: { id } which auto-resolves. But we need account: { id } for row 2.
  // Actually the trusted standard only mentions one GET for the expense account.
  // Let me check if I can use account: { id } for 2400 from a combined query.

  // Step 3: importDocument with EHF XML
  const xml = `<?xml version="1.0" encoding="UTF-8"?>
<Invoice xmlns="urn:oasis:names:specification:ubl:schema:xsd:Invoice-2"
         xmlns:cac="urn:oasis:names:specification:ubl:schema:xsd:CommonAggregateComponents-2"
         xmlns:cbc="urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2">
  <cbc:CustomizationID>urn:cen.eu:en16931:2017#compliant#urn:fdc:peppol.eu:2017:poacc:billing:3.0</cbc:CustomizationID>
  <cbc:ProfileID>urn:fdc:peppol.eu:2017:poacc:billing:01:1.0</cbc:ProfileID>
  <cbc:ID>${inv.number}</cbc:ID>
  <cbc:IssueDate>${inv.date}</cbc:IssueDate>
  <cbc:DueDate>${inv.dueDate}</cbc:DueDate>
  <cbc:InvoiceTypeCode>380</cbc:InvoiceTypeCode>
  <cbc:DocumentCurrencyCode>NOK</cbc:DocumentCurrencyCode>
  <cac:AccountingSupplierParty>
    <cac:Party>
      <cbc:EndpointID schemeID="0192">${supplier.orgNr}</cbc:EndpointID>
      <cac:PartyName><cbc:Name>${supplier.name}</cbc:Name></cac:PartyName>
      <cac:PostalAddress>
        <cbc:StreetName>${supplier.street}</cbc:StreetName>
        <cbc:CityName>${supplier.city}</cbc:CityName>
        <cbc:PostalZone>${supplier.postalCode}</cbc:PostalZone>
        <cac:Country><cbc:IdentificationCode>NO</cbc:IdentificationCode></cac:Country>
      </cac:PostalAddress>
      <cac:PartyTaxScheme>
        <cbc:CompanyID>NO${supplier.orgNr}MVA</cbc:CompanyID>
        <cac:TaxScheme><cbc:ID>VAT</cbc:ID></cac:TaxScheme>
      </cac:PartyTaxScheme>
      <cac:PartyLegalEntity>
        <cbc:RegistrationName>${supplier.name}</cbc:RegistrationName>
        <cbc:CompanyID schemeID="0192">${supplier.orgNr}</cbc:CompanyID>
      </cac:PartyLegalEntity>
    </cac:Party>
  </cac:AccountingSupplierParty>
  <cac:AccountingCustomerParty>
    <cac:Party>
      <cbc:EndpointID schemeID="0192">999999999</cbc:EndpointID>
      <cac:PartyName><cbc:Name>Ditt firma</cbc:Name></cac:PartyName>
      <cac:PostalAddress>
        <cac:Country><cbc:IdentificationCode>NO</cbc:IdentificationCode></cac:Country>
      </cac:PostalAddress>
      <cac:PartyLegalEntity>
        <cbc:RegistrationName>Ditt firma</cbc:RegistrationName>
        <cbc:CompanyID schemeID="0192">999999999</cbc:CompanyID>
      </cac:PartyLegalEntity>
    </cac:Party>
  </cac:AccountingCustomerParty>
  <cac:TaxTotal>
    <cbc:TaxAmount currencyID="NOK">${inv.vat}</cbc:TaxAmount>
    <cac:TaxSubtotal>
      <cbc:TaxableAmount currencyID="NOK">${inv.net}</cbc:TaxableAmount>
      <cbc:TaxAmount currencyID="NOK">${inv.vat}</cbc:TaxAmount>
      <cac:TaxCategory>
        <cbc:ID>S</cbc:ID>
        <cbc:Percent>25</cbc:Percent>
        <cac:TaxScheme><cbc:ID>VAT</cbc:ID></cac:TaxScheme>
      </cac:TaxCategory>
    </cac:TaxSubtotal>
  </cac:TaxTotal>
  <cac:LegalMonetaryTotal>
    <cbc:LineExtensionAmount currencyID="NOK">${inv.net}</cbc:LineExtensionAmount>
    <cbc:TaxExclusiveAmount currencyID="NOK">${inv.net}</cbc:TaxExclusiveAmount>
    <cbc:TaxInclusiveAmount currencyID="NOK">${inv.gross}</cbc:TaxInclusiveAmount>
    <cbc:PayableAmount currencyID="NOK">${inv.gross}</cbc:PayableAmount>
  </cac:LegalMonetaryTotal>
  <cac:InvoiceLine>
    <cbc:ID>1</cbc:ID>
    <cbc:InvoicedQuantity unitCode="EA">1</cbc:InvoicedQuantity>
    <cbc:LineExtensionAmount currencyID="NOK">${inv.net}</cbc:LineExtensionAmount>
    <cac:Item>
      <cbc:Name>${inv.description}</cbc:Name>
      <cac:ClassifiedTaxCategory>
        <cbc:ID>S</cbc:ID>
        <cbc:Percent>25</cbc:Percent>
        <cac:TaxScheme><cbc:ID>VAT</cbc:ID></cac:TaxScheme>
      </cac:ClassifiedTaxCategory>
    </cac:Item>
    <cac:Price>
      <cbc:PriceAmount currencyID="NOK">${inv.net}</cbc:PriceAmount>
    </cac:Price>
  </cac:InvoiceLine>
</Invoice>`;

  const formData = new FormData();
  formData.append("file", new Blob([xml], { type: "text/xml" }), `${inv.number}.xml`);
  const importRes = await api("POST", "/ledger/voucher/importDocument", formData, "formdata");
  const voucherId = importRes.values[0].id;
  const voucherVersion = importRes.values[0].version;
  console.log("Voucher ID:", voucherId, "Version:", voucherVersion);

  // Step 4: Set postings with sendToLedger=false
  const putRes = await api("PUT", `/ledger/voucher/${voucherId}?sendToLedger=false`, {
    version: voucherVersion,
    postings: [
      {
        row: 1,
        account: { id: expenseAccountId },
        description: inv.description,
        vatType: { id: 1 },
        amount: inv.net,
        amountCurrency: inv.net,
        amountGross: inv.gross,
        amountGrossCurrency: inv.gross,
      },
      {
        row: 2,
        account: { id: expenseAccountId }, // placeholder — will fix below
        supplier: { id: supplierId },
        description: inv.description,
        amount: -inv.gross,
        amountCurrency: -inv.gross,
        amountGross: -inv.gross,
        amountGrossCurrency: -inv.gross,
        invoiceNumber: inv.number,
        termOfPayment: inv.dueDate,
      },
    ],
  });
  const putVersion = putRes.value.version;
  console.log("Postings set, version:", putVersion);

  // Step 5: Book with sendToLedger=true
  const bookRes = await api("PUT", `/ledger/voucher/${voucherId}?sendToLedger=true`, {
    version: putVersion,
    voucherType: { name: "Leverandørfaktura" },
  });
  console.log("Booked! Voucher number:", bookRes.value.number);
  console.log("Done. 5 API calls.");
}

main().catch((e) => { console.error(e); process.exit(1); });

